let p = msg.payload;

if (Buffer.isBuffer(p)) {
    p = p.toString();
}

if (typeof p === "string") {
    try {
        p = JSON.parse(p);
    } catch (err) {
        node.error("Payload MQTT bukan JSON valid: " + err.message, msg);
        return null;
    }
}

if (!p || typeof p !== "object" || Array.isArray(p)) {
    node.error("Payload sensor bukan object", msg);
    return null;
}

if (typeof p.node_id !== "string" || !p.node_id.trim()) {
    node.warn("Payload tidak memiliki node_id yang valid");
    return null;
}

function toBoolean(value) {
    if (value === true || value === 1) return true;

    if (typeof value === "string") {
        return ["true", "1", "yes"].includes(
            value.trim().toLowerCase()
        );
    }

    return false;
}

function normalizeNumber(field, min, max) {
    if (
        p[field] === undefined ||
        p[field] === null ||
        p[field] === ""
    ) {
        p[field] = null;
        return;
    }

    const value = Number(p[field]);

    if (
        !Number.isFinite(value) ||
        value < min ||
        value > max
    ) {
        node.warn(`${field} tidak valid: ${p[field]}`);
        p[field] = null;
        return;
    }

    p[field] = value;
}

normalizeNumber("temp", -40, 80);
normalizeNumber("hum", 0, 100);
normalizeNumber("wind_speed", 0, 100);
normalizeNumber("soil_moisture", 0, 100);

normalizeNumber("co", 0, 2000);
normalizeNumber("ch4", 0, 10000);

for (const field of [
    "mq2_raw",
    "mq7_raw",
    "soil_raw"
]) {
    normalizeNumber(field, 0, 4095);
}

for (const field of [
    "mq2_vout_v",
    "mq7_vout_v"
]) {
    normalizeNumber(field, 0, 5);
}

for (const field of [
    "mq2_rs_kohm",
    "mq7_rs_kohm",
    "mq2_r0_kohm",
    "mq7_r0_kohm"
]) {
    normalizeNumber(field, 0, 100000);

    if (p[field] !== null && p[field] <= 0) {
        p[field] = null;
    }
}

normalizeNumber("mq2_response_percent", 0, 100000);
normalizeNumber("mq7_response_percent", 0, 100000);

p.gas_calibrated = toBoolean(p.gas_calibrated);
p.gas_calibration_validated =
    toBoolean(p.gas_calibration_validated);

p.mq7_heater_cycle_compliant =
    toBoolean(p.mq7_heater_cycle_compliant);

p.gas_baseline_ready =
    toBoolean(p.gas_baseline_ready);

p.mq2_signal_change_detected =
    toBoolean(p.mq2_signal_change_detected);

p.mq7_signal_change_detected =
    toBoolean(p.mq7_signal_change_detected);

p.gas_signal_change_detected =
    toBoolean(p.gas_signal_change_detected);

const ppmAvailable =
    Number.isFinite(p.co) &&
    Number.isFinite(p.ch4);

if (!p.gas_calibrated || !ppmAvailable) {
    p.gas_calibrated = false;
    p.co = null;
    p.ch4 = null;
    p.gas_calibration_validated = false;
}

const gasStandardValidated =
    p.gas_calibrated &&
    p.gas_calibration_validated &&
    p.mq7_heater_cycle_compliant &&
    p.gas_calibration_status === "GAS_STANDARD_VALIDATED";

if (gasStandardValidated) {
    p.gas_calibration_status = "GAS_STANDARD_VALIDATED";
    p.gas_calibration_validated = true;
} else if (p.gas_calibrated) {
    p.gas_calibration_status = "PROVISIONAL_CURVE_ESTIMATE";
    p.gas_calibration_validated = false;
} else {
    p.gas_calibration_status = "NOT_CALIBRATED";
    p.gas_calibration_validated = false;
}

if (!p.gas_calibration_method) {
    p.gas_calibration_method = "UNKNOWN";
}

if (typeof p.soil_condition !== "string") {
    p.soil_condition = "";
}

p.soil_condition = p.soil_condition.trim();

if (
    !p.soil_condition &&
    Number.isFinite(p.soil_moisture)
) {
    if (p.soil_moisture >= 60) {
        p.soil_condition = "Tanah Basah";
    } else if (p.soil_moisture >= 30) {
        p.soil_condition = "Tanah Lembap";
    } else {
        p.soil_condition = "Tanah Kering";
    }
}

if (!p.soil_condition) {
    p.soil_condition = "Tidak diketahui";
}

p.sensor_timestamp = p.timestamp ?? null;
p.timestamp = new Date().toISOString();

p.sample_id =
    p.sample_id ||
    `${p.node_id}:${p.uptime_ms ?? Date.now()}`;

msg.payload = p;
msg.sample_id = p.sample_id;

node.status({
    fill: "green",
    shape: "dot",
    text: `Sampel ${p.node_id} valid`
});

return msg;

const d = msg.payload || {};

function clamp01(value) {
    return Math.min(Math.max(value, 0), 1);
}

function fT(temperature) {
    if (!Number.isFinite(temperature)) return NaN;
    if (temperature < 25) return 0;
    if (temperature > 55) return 1;

    return (temperature - 25) / 30;
}

function fH(humidity) {
    if (!Number.isFinite(humidity)) return NaN;
    if (humidity < 30) return 1;
    if (humidity > 90) return 0;

    return (90 - humidity) / 60;
}

function fCO(coPpm) {
    if (!Number.isFinite(coPpm)) return NaN;

    return clamp01(coPpm / 200);
}

function fCH4(ch4Ppm) {
    if (!Number.isFinite(ch4Ppm)) return NaN;

    return clamp01(ch4Ppm / 1000);
}

const environmentValid =
    Number.isFinite(d.temp) &&
    Number.isFinite(d.hum);

const gasValid =
    d.gas_calibrated === true &&
    Number.isFinite(d.co) &&
    Number.isFinite(d.ch4);

const gasStandardValidated =
    d.gas_calibration_validated === true &&
    d.gas_calibration_status === "GAS_STANDARD_VALIDATED" &&
    d.mq7_heater_cycle_compliant === true;

let fri = null;
let friLevel = "UNKNOWN";
let friDataStatus = "WAITING_FOR_CALIBRATED_GAS_PPM";

let ft = null;
let fh = null;
let fco = null;
let fch4 = null;
let fg = null;

if (!environmentValid) {
    friDataStatus = "MISSING_TEMPERATURE_OR_HUMIDITY";
} else if (!gasValid) {
    friDataStatus = "WAITING_FOR_CALIBRATED_GAS_PPM";
} else {
    ft = fT(d.temp);
    fh = fH(d.hum);
    fco = fCO(d.co);
    fch4 = fCH4(d.ch4);

    fg = Math.max(fco, fch4);

    fri =
        (0.3 * ft) +
        (0.2 * fh) +
        (0.5 * fg);

    fri = clamp01(fri);

    if (fri < 0.4) {
        friLevel = "Low";
    } else if (fri <= 0.6) {
        friLevel = "Moderate";
    } else if (fri <= 0.8) {
        friLevel = "High";
    } else {
        friLevel = "Extreme";
    }

    friDataStatus = gasStandardValidated
        ? "COMPLETE_GAS_STANDARD_VALIDATED"
        : "PROVISIONAL_GAS_CURVE_ESTIMATE";
}

msg.payload = {
    ...d,

    fri_f_temperature: ft,
    fri_f_humidity: fh,
    fri_f_co: fco,
    fri_f_ch4: fch4,
    fri_f_gas: fg,

    fri_base: fri === null
        ? null
        : Number(fri.toFixed(4)),

    fri: fri === null
        ? null
        : Number(fri.toFixed(3)),

    fri_level: friLevel,
    fri_data_status: friDataStatus
};

msg.analytics_data = { ...msg.payload };

flow.set("last_fri_data", msg.payload);

node.status({
    fill: fri === null ? "grey" :
        friLevel === "Low" ? "green" :
            friLevel === "Moderate" ? "yellow" :
                friLevel === "High" ? "orange" : "red",
    shape: "dot",
    text: fri === null
        ? `FRI N/A | ${friDataStatus}`
        : `FRI ${fri.toFixed(3)} | ${friLevel} | ${friDataStatus}`
});

return msg;

// ============================================================
// PREPARE ML INPUT  (PyroWatch ML v4: skenario + eskalasi 30 menit)
// Output 1 -> HTTP Request ML, Output 2 -> dashboard (tanpa panggil ML)
// ============================================================
const data = msg.payload;
if (!data || typeof data !== "object" || Array.isArray(data)) {
    node.error("Data sensor untuk ML tidak valid.", msg);
    return [null, null];
}
const snapshot = JSON.parse(JSON.stringify(data));
msg.analytics_data = snapshot;
msg.sensor_data = snapshot;

const HORIZON = 30;
const nodeId = String(snapshot.node_id || "unknown");
const isNum = v => v !== null && v !== undefined && v !== "" && Number.isFinite(Number(v));
const fri = Number(snapshot.fri);

// ---------------- FRI tidak valid: ML tidak dipanggil
if (!isNum(snapshot.fri) || fri < 0 || fri > 1) {
    msg.ml_result = {
        forecast_status: "INSUFFICIENT_INPUTS", forecast_horizon_minutes: HORIZON,
        insight_text: "Analisis ML tidak tersedia karena FRI belum valid (sensor gas belum terkalibrasi atau suhu/kelembapan hilang).",
        trend: "UNKNOWN", fri_change: null, highlights: [],
        recommendations: {
            priority: "DATA_CHECK",
            trigger_summary: `Status data: ${snapshot.fri_data_status || "UNKNOWN"}.`,
            monitoring: "Periksa kalibrasi MQ-7/MQ-2 (R0, heater cycle) dan sensor DHT22 sebelum memakai analisis risiko.",
            early_response: "Tanpa FRI valid, respons lapangan mengikuti observasi visual petugas dan SOP.",
            area_protection: "Lakukan patroli rutin di sekitar node sampai data sensor pulih.",
            coordination: "Laporkan gangguan data ke teknisi.",
            operational_caveat: "Status UNKNOWN bukan berarti aman.",
            action_plan: []
        },
        forecast_model_version: null, input_status: "MISSING_OR_INVALID_FRI"
    };
    msg.payload = snapshot;
    node.status({ fill: "yellow", shape: "ring", text: "ML dilewati: FRI tidak valid" });
    return [null, msg];
}

// ---------------- Throttle 60 detik per node (data simulasi tidak di-throttle)
const throttleKey = `ml_last_request_${nodeId}`;
const cacheKey = `ml_last_result_${nodeId}`;
const now = Date.now();
const lastRequest = Number(flow.get(throttleKey) || 0);
if (snapshot.simulation !== true && now - lastRequest < 60000) {
    // Pakai hasil analisis terakhir agar dashboard tidak kehilangan rekomendasi.
    const cached = flow.get(cacheKey);
    if (cached) {
        msg.ml_result = { ...cached, forecast_status: "CACHED", input_status: "WAITING_INTERVAL",
            cached_from_sample: cached.sample_timestamp ?? null };
    } else {
        msg.ml_result = { forecast_status: "THROTTLED", forecast_horizon_minutes: HORIZON,
            insight_text: "Analisis ML pertama untuk node ini sedang menunggu interval 60 detik.",
            trend: "UNKNOWN", fri_change: null, highlights: [], recommendations: null,
            forecast_model_version: null, input_status: "WAITING_INTERVAL" };
    }
    msg.payload = snapshot;
    node.status({ fill: "grey", shape: "ring", text: "Interval 60 dtk: pakai hasil ML terakhir" });
    return [null, msg];
}
flow.set(throttleKey, now);

// ---------------- Payload ML
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    node_id: snapshot.node_id,
    timestamp: snapshot.timestamp,
    co: snapshot.gas_calibrated === true ? snapshot.co ?? null : null,
    ch4: snapshot.gas_calibrated === true ? snapshot.ch4 ?? null : null,
    gas_calibrated: snapshot.gas_calibrated === true,
    gas_calibration_validated: snapshot.gas_calibration_validated === true,
    gas_calibration_status: snapshot.gas_calibration_status ?? "NOT_CALIBRATED",
    temp: snapshot.temp ?? null,
    hum: snapshot.hum ?? null,
    fri: fri,
    fri_level: snapshot.fri_level ?? "UNKNOWN",
    wind_speed_sensor: snapshot.wind_speed_sensor ?? snapshot.wind_speed ?? null,   // anemometer ESP32
    wind_direction_deg: snapshot.wind_direction_deg ?? null,                         // Open-Meteo (arah datang angin)
    wind_direction: snapshot.wind_direction ?? "UNKNOWN",
    spread_rate_cmph: snapshot.spread_rate_cmph ?? null,                             // baseline semi-empiris
    soil_condition: snapshot.soil_condition ?? "Tidak diketahui",
    soil_moisture: snapshot.soil_moisture ?? null,
    rain: snapshot.rain ?? null
};
node.status({ fill: "green", shape: "dot", text: `Kirim ke ML (${nodeId})` });
return [msg, null];

const r = msg.payload || {};
const sample = msg.analytics_data || msg.sensor_data || {};
const HORIZON = 30;

if (!r.forecast_status || r.forecast_status === "ERROR") {
    msg.ml_result = {
        forecast_status: r.forecast_status === "ERROR" ? "ML_ERROR" : "ML_RESPONSE_INVALID",
        forecast_horizon_minutes: HORIZON,
        insight_text: r.error ? `Layanan ML error: ${r.error}` : "Respons ML tidak sesuai format.",
        trend: "UNKNOWN", fri_change: null, highlights: [], recommendations: null,
        forecast_model_version: null, input_status: "INVALID_RESPONSE"
    };
    msg.payload = { ...sample };
    node.status({ fill: "red", shape: "ring", text: "Respons ML tidak valid" });
    return [msg, null];
}

const rec = r.recommendations || null;
const esc = r.escalation || {};
const spread = r.spread || {};

msg.ml_result = {
    forecast_status: r.forecast_status,
    forecast_horizon_minutes: r.forecast_horizon_minutes ?? HORIZON,
    sample_timestamp: r.sample_timestamp ?? sample.timestamp,
    forecast_timestamp: r.forecast_timestamp ?? null,
    current_fri: r.current_fri ?? sample.fri,
    current_fri_level: r.current_fri_level ?? sample.fri_level,
    // --- analisis skenario
    scenario: r.scenario ?? null,
    scenario_label: r.scenario_label ?? null,
    scenario_confidence: r.scenario_confidence ?? null,
    scenario_probabilities: r.scenario_probabilities ?? {},
    drivers: r.drivers ?? null,
    // --- prediksi
    escalation: esc,
    trend: r.trend ?? "UNKNOWN",
    fri_change: r.fri_change ?? null,
    component_projection_15m: r.component_projection_15m ?? {},
    component_trend_per_min: r.component_trend_per_min ?? {},
    spread: spread,
    future_wind_speed: r.future_wind_speed ?? null,
    future_wind_direction: r.future_wind_direction ?? null,
    future_spread_rate_cmph: r.future_spread_rate_cmph ?? null,
    future_spread_direction: r.future_spread_direction ?? null,
    spread_direction_probability: r.spread_direction_probability ?? null,
    forecast_confidence: r.forecast_confidence ?? null,
    forecast_interpretation: r.forecast_interpretation ?? null,
    // --- narasi & rekomendasi
    insight_text: r.insight_text ?? "Analisis tidak tersedia.",
    highlights: Array.isArray(r.highlights) ? r.highlights : [],
    recommendations: rec,
    data_quality: Array.isArray(r.data_quality) ? r.data_quality : [],
    history_points_used: r.history_points_used ?? null,
    forecast_model_version: r.forecast_model_version ?? null,
    input_status: r.input_status ?? "UNKNOWN"
};

// Cache per node untuk dipakai saat throttle.
if (sample.node_id) flow.set(`ml_last_result_${sample.node_id}`, msg.ml_result);

msg.ml_forecast = {
    node_id: sample.node_id,
    sample_timestamp: r.sample_timestamp ?? sample.timestamp,
    forecast_timestamp: r.forecast_timestamp ?? null,
    forecast_horizon_minutes: r.forecast_horizon_minutes ?? HORIZON,
    forecast_status: r.forecast_status,
    current_fri: r.current_fri ?? sample.fri,
    fri_change_30m: esc.fri_change_30m ?? null,
    p_high_30m: esc.p_high_30m ?? null,
    p_extreme_30m: esc.p_extreme_30m ?? null,
    scenario: r.scenario ?? null,
    priority: rec ? rec.priority : null,
    future_wind_speed: r.future_wind_speed ?? null,
    future_wind_direction: r.future_wind_direction ?? null,
    future_spread_rate_cmph: r.future_spread_rate_cmph ?? null,
    spread_mode: spread.mode ?? null,
    future_spread_direction: r.future_spread_direction ?? null,
    spread_direction_probability: r.spread_direction_probability ?? null,
    forecast_confidence: r.forecast_confidence ?? null,
    forecast_interpretation: r.forecast_interpretation ?? null,
    forecast_model_version: r.forecast_model_version ?? null
};

const dashboardMsg = { ...msg, payload: { ...sample } };
const sqliteMsg = { ...msg, payload: { ...sample }, ml_forecast: { ...msg.ml_forecast } };
const pr = rec ? rec.priority : "-";
node.status({
    fill: pr === "URGENT" ? "red" : pr === "ELEVATED" ? "orange" : pr === "WATCH" || pr === "DATA_CHECK" ? "yellow" : "green",
    shape: "dot",
    text: `${r.scenario || "?"} | ${pr} | High30 ${Math.round((esc.p_high_30m ?? 0) * 100)}%`
});
return [dashboardMsg, sqliteMsg];

const data = msg.payload;
if (!data || typeof data !== "object") {
    node.error("Data sensor sebelum Weather API tidak valid", msg);
    return null;
}
msg.sensor_data = { ...data };
msg.analytics_data = { ...data };
delete msg.url;
delete msg.method;
return msg;

const weather = msg.payload || {};

// Snapshot sensor sebelum request Open-Meteo
const d = msg.sensor_data || msg.analytics_data;

if (!d || typeof d !== "object") {
    node.error("Snapshot sensor hilang setelah Weather API", msg);
    return null;
}

const current = weather.current || {};

function validNumber(value) {
    if (
        value === null ||
        value === undefined ||
        value === ""
    ) {
        return null;
    }

    const number = Number(value);

    return Number.isFinite(number)
        ? number
        : null;
}

// ============================================
// 1. KECEPATAN ANGIN DARI ANEMOMETER ESP32
// ============================================

const sensorWindSpeed = validNumber(
    d.wind_speed_sensor ?? d.wind_speed
);

// ============================================
// 2. ARAH ANGIN DARI OPEN-METEO
// ============================================

const directionDeg = validNumber(
    current.wind_direction_10m
);

const directions = [
    "N",
    "NE",
    "E",
    "SE",
    "S",
    "SW",
    "W",
    "NW"
];

let direction = "UNKNOWN";

if (directionDeg !== null) {
    const index =
        Math.round(directionDeg / 45) % 8;

    direction = directions[index];
}

// ============================================
// 3. STATUS DATA WEATHER
// ============================================

const weatherStatus =
    directionDeg !== null
        ? "OK"
        : "DIRECTION_UNAVAILABLE";

// ============================================
// 4. GABUNGKAN DATA
// ============================================

msg.payload = {
    ...d,

    // Kecepatan angin hanya dari ESP32
    wind_speed: sensorWindSpeed,
    wind_speed_sensor: sensorWindSpeed,

    // Tidak menggunakan kecepatan Open-Meteo
    wind_speed_weather: null,

    // Arah angin hanya dari Open-Meteo
    wind_direction_deg: directionDeg,
    wind_direction: direction,

    weather_source: "Open-Meteo",
    weather_status: weatherStatus,

    rain: validNumber(current.rain)
};

msg.analytics_data = {
    ...msg.payload
};

node.status({
    fill: weatherStatus === "OK"
        ? "green"
        : "yellow",

    shape: "dot",

    text:
        `Anemometer ${sensorWindSpeed ?? "-"} m/s | ` +
        `Arah ${direction}`
});

return msg;

const d = msg.payload || {};

// ============================================
// PARAMETER MODEL BASELINE
// ============================================

const BASE_SPREAD_CMPH = 2.7;

const C1 = 0.045;
const C2 = 0.131;

// ============================================
// INPUT ANGIN
// ============================================

// Kecepatan angin dari anemometer ESP32
const windSpeed = Number(
    d.wind_speed_sensor ?? d.wind_speed
);

// Arah angin dari Open-Meteo
const directionRaw = Number(
    d.wind_direction_deg
);

// ============================================
// VALIDASI KECEPATAN ANGIN
// ============================================

if (
    !Number.isFinite(windSpeed) ||
    windSpeed < 0
) {
    msg.payload = {
        ...d,

        spread_rate_base_cmph:
            BASE_SPREAD_CMPH,

        wind_effect_factor: null,

        spread_rate_cmph: null,

        spread_model: "Unavailable",

        spread_model_status:
            "WIND_SPEED_UNAVAILABLE",

        spread_model_reference: null,

        spread_label_type:
            "SEMI_EMPIRICAL_ESTIMATE_NOT_GROUND_TRUTH"
    };

    msg.analytics_data = {
        ...msg.payload
    };

    node.status({
        fill: "yellow",
        shape: "ring",
        text: "Spread estimate unavailable"
    });

    return msg;
}

// ============================================
// PERHITUNGAN BASELINE SPREAD
// ============================================

// Catatan:
// theta = 0 mempertahankan asumsi rumus
// baseline pada flow sebelumnya.
// Arah Open-Meteo diteruskan sebagai fitur
// untuk analisis ML, bukan faktor rumus ini.

const theta = 0;

const windEffectFactor = Math.exp(
    windSpeed * (
        C1 - C2 * (1 - Math.cos(theta))
    )
);

const spreadRate =
    BASE_SPREAD_CMPH * windEffectFactor;

// ============================================
// SIMPAN HASIL PERHITUNGAN
// ============================================

msg.payload = {
    ...d,

    spread_rate_base_cmph:
        BASE_SPREAD_CMPH,

    wind_effect_factor:
        Number(windEffectFactor.toFixed(4)),

    spread_rate_cmph:
        Number(spreadRate.toFixed(2)),

    // Arah angin tetap berasal dari Open-Meteo
    wind_direction_deg:
        Number.isFinite(directionRaw)
            ? Number(directionRaw.toFixed(1))
            : null,

    wind_direction:
        d.wind_direction || "UNKNOWN",

    spread_model:
        "Tropical peatland semi-empirical wind-adjusted model",

    spread_model_status: "ESTIMATE",

    spread_model_reference:
        "Huang et al. field baseline + wind effect adaptation",

    spread_direction_source:
        "Open-Meteo meteorological wind direction",

    spread_label_type:
        "SEMI_EMPIRICAL_ESTIMATE_NOT_GROUND_TRUTH"
};

msg.analytics_data = {
    ...msg.payload
};

flow.set(
    "last_fri_data",
    msg.payload
);

node.status({
    fill: "green",
    shape: "dot",
    text:
        `Baseline spread ${spreadRate.toFixed(2)} cm/h`
});

return msg;

const d = msg.analytics_data || msg.payload || msg.sensor_data || {};
const ml = msg.ml_result || {};
const rec = ml.recommendations || null;
const esc = ml.escalation || {};
const spread = ml.spread || {};
const gasOk = d.gas_calibrated === true;
const out = {
    sample_id: d.sample_id || msg.sample_id || null, node_id: d.node_id ?? null,
    timestamp: d.timestamp || new Date().toISOString(), sensor_timestamp: d.sensor_timestamp ?? null,
    simulation: d.simulation === true, simulation_scenario: d.simulation_scenario ?? null,
    // ---------------- sensor
    temp: d.temp ?? null, hum: d.hum ?? null,
    co: gasOk ? d.co ?? null : null, ch4: gasOk ? d.ch4 ?? null : null,
    gas_calibrated: gasOk, gas_calibration_validated: d.gas_calibration_validated === true,
    gas_calibration_status: d.gas_calibration_status || "NOT_CALIBRATED", gas_calibration_method: d.gas_calibration_method || "UNKNOWN",
    mq7_heater_cycle_compliant: d.mq7_heater_cycle_compliant === true, mq2_raw: d.mq2_raw ?? null, mq7_raw: d.mq7_raw ?? null,
