    mq7_response_percent: d.mq7_response_percent ?? null, mq2_signal_change_detected: d.mq2_signal_change_detected === true,
    mq7_signal_change_detected: d.mq7_signal_change_detected === true, gas_signal_change_detected: d.gas_signal_change_detected === true,
    soil_raw: d.soil_raw ?? null, soil_moisture: d.soil_moisture ?? null, soil_condition: d.soil_condition || "Tidak diketahui",
    wind_speed: d.wind_speed ?? null, wind_speed_sensor: d.wind_speed_sensor ?? d.wind_speed ?? null, wind_speed_weather: null,
    wind_direction_deg: d.wind_direction_deg ?? null, wind_direction: d.wind_direction || "UNKNOWN",
    weather_source: d.weather_source || "Open-Meteo", weather_status: d.weather_status || "UNKNOWN", rain: d.rain ?? null,
    // ---------------- FRI resmi (sensor)
    fri_f_temperature: d.fri_f_temperature ?? null, fri_f_humidity: d.fri_f_humidity ?? null, fri_f_co: d.fri_f_co ?? null,
    fri_f_ch4: d.fri_f_ch4 ?? null, fri_f_gas: d.fri_f_gas ?? null, fri_base: d.fri_base ?? null, fri: d.fri ?? null,
    fri_level: d.fri_level || "UNKNOWN", fri_data_status: d.fri_data_status || "WAITING_FOR_CALIBRATED_GAS_PPM",
    spread_rate_base_cmph: d.spread_rate_base_cmph ?? null, wind_effect_factor: d.wind_effect_factor ?? null,
    spread_rate_cmph: d.spread_rate_cmph ?? null, spread_model: d.spread_model || "Unavailable", spread_model_status: d.spread_model_status || "UNKNOWN",
    spread_model_reference: d.spread_model_reference ?? null, spread_direction_source: d.spread_direction_source ?? null,
    spread_label_type: d.spread_label_type || "SEMI_EMPIRICAL_ESTIMATE_NOT_GROUND_TRUTH",
    // ---------------- ML: status
    ml_forecast_status: ml.forecast_status || "UNAVAILABLE", ml_forecast_horizon_minutes: ml.forecast_horizon_minutes ?? 30,
    ml_forecast_timestamp: ml.forecast_timestamp ?? null, ml_model_version: ml.forecast_model_version ?? null,
    ml_input_status: ml.input_status ?? "UNKNOWN", ml_cached_from_sample: ml.cached_from_sample ?? null,
    ml_history_points_used: ml.history_points_used ?? null, ml_data_quality: Array.isArray(ml.data_quality) ? ml.data_quality : [],
    // ---------------- ML: analisis skenario (mengapa FRI bernilai sekian)
    ml_scenario: ml.scenario ?? null, ml_scenario_label: ml.scenario_label ?? null,
    ml_scenario_confidence: ml.scenario_confidence ?? null, ml_scenario_probabilities: ml.scenario_probabilities ?? {},
    ml_drivers: ml.drivers ?? null,
    ml_dominant_driver: ml.drivers ? ml.drivers.dominant_driver ?? null : null,
    // ---------------- ML: prediksi
    ml_trend: ml.trend ?? "UNKNOWN", ml_fri_change: ml.fri_change ?? null,
    ml_p_high_30m: esc.p_high_30m ?? null, ml_p_extreme_30m: esc.p_extreme_30m ?? null,
    ml_eta_high_min: esc.eta_high_min ?? null, ml_eta_extreme_min: esc.eta_extreme_min ?? null,
    ml_fri_change_15m: esc.fri_change_15m ?? null, ml_fri_change_30m: esc.fri_change_30m ?? null,
    ml_component_projection_15m: ml.component_projection_15m ?? {}, ml_component_trend_per_min: ml.component_trend_per_min ?? {},
    ml_current_fri: ml.current_fri ?? d.fri ?? null, ml_current_fri_level: ml.current_fri_level ?? d.fri_level ?? "UNKNOWN",
    ml_future_wind_speed: ml.future_wind_speed ?? null, ml_future_spread_rate_cmph: ml.future_spread_rate_cmph ?? null,
    // ---------------- ML: rambat & sektor
    ml_spread: spread, ml_spread_mode: spread.mode ?? null,
    ml_source_search_sector: spread.source_search_sector ?? null, ml_threat_sector: spread.threat_sector ?? null,
    ml_inspection_radius_m: spread.inspection_radius_m ?? null,
    // ---------------- ML: narasi & rekomendasi
    ml_insight_text: ml.insight_text ?? "Analisis ML belum tersedia.",
    ml_highlights: Array.isArray(ml.highlights) ? ml.highlights : [],
    ml_priority: rec ? rec.priority ?? null : null,
    ml_action_plan: rec && Array.isArray(rec.action_plan) ? rec.action_plan : [],
    ml_ppe: rec ? rec.ppe ?? null : null, ml_sampling_interval: rec ? rec.sampling_interval ?? null : null,
    ml_recommendations: rec
};
msg.dashboard_data = out;
msg.payload = out;
msg.sample_id = out.sample_id;
flow.set("last_pyrowatch_payload", out);
const hist = flow.get("pyrowatch_node_latest") || {};
if (out.node_id) { hist[out.node_id] = out; flow.set("pyrowatch_node_latest", hist); }
node.status({ fill: "green", shape: "dot", text: `${out.node_id} | ${out.ml_scenario || "-"} | ${out.ml_priority || "-"}` });
return msg;

const data = flow.get("last_pyrowatch_payload");

if (!data) {
    msg.statusCode = 404;
    msg.payload = {
        success: false,
        message: "Belum ada data sensor"
    };
    return msg;
}

msg.statusCode = 200;
msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = {
    success: true,
    data: data
};

return msg;

const sample = msg.analytics_data || msg.sensor_data || {};
const cached = sample.node_id ? flow.get(`ml_last_result_${sample.node_id}`) : null;
msg.ml_result = {
    forecast_status: "ML_REQUEST_FAILED", forecast_horizon_minutes: 30,
    insight_text: "Analisis ML gagal diakses (container ml:5000). " +
        (cached ? `Menampilkan rekomendasi terakhir dari sampel ${cached.sample_timestamp}; perlakukan sebagai informasi lama.` :
            "Belum ada hasil sebelumnya."),
    trend: "UNKNOWN", fri_change: null, highlights: cached ? cached.highlights || [] : [],
    scenario: cached ? cached.scenario : null, scenario_label: cached ? cached.scenario_label : null,
    recommendations: {
        priority: "DATA_CHECK",
        trigger_summary: "Analisis model tidak tersedia.",
        monitoring: "Periksa status container ML (docker compose ps / logs ml) dan koneksi Node-RED ke ml:5000.",
        early_response: "Jangan memakai hasil model yang gagal sebagai dasar respons; ikuti SOP dan verifikasi lapangan.",
        area_protection: "Tentukan area prioritas berdasarkan nilai FRI sensor dan observasi petugas.",
        coordination: "Informasikan gangguan prediksi kepada teknisi dan koordinator.",
        operational_caveat: "Keputusan lapangan tetap mengikuti SOP dan konfirmasi petugas.",
        action_plan: cached && cached.recommendations ? cached.recommendations.action_plan || [] : []
    },
    forecast_model_version: null, input_status: "ML_API_UNAVAILABLE"
};
msg.payload = { ...sample };
delete msg.error;
node.status({ fill: "red", shape: "ring", text: "ML API gagal" });
return msg;

const f = msg.ml_forecast || {};
if (!f.node_id || !f.sample_timestamp) {
    node.warn("Forecast tidak disimpan: node_id atau sample_timestamp tidak tersedia.");
    return null;
}
const num = v => (v !== null && v !== undefined && v !== "" && Number.isFinite(Number(v))) ? Number(v) : null;
const horizon = num(f.forecast_horizon_minutes) ?? 30;
const forecastTimestamp = f.forecast_timestamp ||
    new Date(new Date(f.sample_timestamp).getTime() + horizon * 60000).toISOString();

// future_fri dan future_fri_level sengaja NULL: FRI resmi berasal dari sensor,
// ML menyimpan perubahan/rentang & probabilitas eskalasi, bukan skor FRI kedua.
const c = f.fri_change_30m;
const friRange = c ? `dFRI30 ${Number(c.expected).toFixed(3)} [${Number(c.low).toFixed(3)}..${Number(c.high).toFixed(3)}]; ` +
    `pHigh30=${num(f.p_high_30m)}; pExt30=${num(f.p_extreme_30m)}` : null;
const spreadRange = num(f.future_spread_rate_cmph) !== null
    ? `${f.spread_mode || "estimasi"}: ${num(f.future_spread_rate_cmph)} cm/jam` : (f.spread_mode || null);

msg.params = [
    f.node_id,
    f.sample_timestamp,
    forecastTimestamp,
    horizon,
    num(f.current_fri),
    null,                              // future_fri (tidak dipakai lagi)
    null,                              // future_fri_level (tidak dipakai lagi)
    friRange,                          // future_fri_range -> rentang perubahan + probabilitas eskalasi
    num(f.future_wind_speed),
    null,                              // future_wind_speed_range
    f.future_wind_direction ?? null,
    spreadRange,                       // future_spread_rate_range
    f.future_spread_direction ?? null, // sektor hilir angin (arah ancaman)
    num(f.spread_direction_probability),
    num(f.forecast_confidence),        // keyakinan skenario
    f.forecast_status ?? "UNKNOWN",
    f.forecast_interpretation ?? `scenario=${f.scenario}; priority=${f.priority}`,
    f.forecast_model_version ?? null
];
return msg;

// ============================================================
// PYROWATCH SENSOR SIMULATION - DINAMIS (deret waktu)
// Mengirim N pembacaan berurutan (1 menit virtual per pembacaan) agar ML
// dapat membaca tren. Pembacaan terakhir bertimestamp "sekarang".
// Payload inject = nama skenario, mis. "EARLY_SMOLDERING".
// ============================================================
let scenario = String(msg.payload || "MODERATE").trim().toUpperCase();
const aliases = { TEST: "MODERATE", TEST_LOW: "LOW", TEST_MODERATE: "MODERATE", TEST_HIGH: "HIGH",
    TEST_EXTREME: "EXTREME", TEST_WIND: "WIND_STRESS", TEST_GAS: "GAS_SPIKE", TEST_HOT_DRY: "HOT_DRY" };
scenario = aliases[scenario] || scenario;
const STEPS = 10;

// f(i) -> nilai pada menit ke-i (0..STEPS-1). Statis = skenario lama.
const statik = (o) => (i) => o;
const scenarios = {
    // --- skenario statis lama (nilai konstan + noise kecil)
    LOW:         statik({ temp: 28, hum: 80, co: 20, ch4: 80, wind: 0.8, dir: 45, soil: "Lembap", moisture: 55 }),
    MODERATE:    statik({ temp: 40, hum: 45, co: 80, ch4: 400, wind: 3.2, dir: 135, soil: "Kering", moisture: 22 }),
    HIGH:        statik({ temp: 45, hum: 50, co: 140, ch4: 600, wind: 4.5, dir: 135, soil: "Kering", moisture: 18 }),
    EXTREME:     statik({ temp: 55, hum: 25, co: 190, ch4: 950, wind: 7.0, dir: 225, soil: "Sangat Kering", moisture: 10 }),
    WIND_STRESS: statik({ temp: 38, hum: 35, co: 70, ch4: 250, wind: 8.5, dir: 90, soil: "Kering", moisture: 20 }),
    GAS_SPIKE:   statik({ temp: 35, hum: 60, co: 180, ch4: 900, wind: 2.0, dir: 180, soil: "Lembap", moisture: 45 }),
    HOT_DRY:     statik({ temp: 50, hum: 25, co: 80, ch4: 300, wind: 5.2, dir: 270, soil: "Sangat Kering", moisture: 8 }),
    // --- skenario dinamis (FRI akhir serupa ~0,45-0,55, penyebab berbeda)
    FUEL_DRYING:       (i) => ({ temp: 46 + 0.1 * i, hum: 34 - 0.1 * i, co: 5, ch4: 40, wind: 3.0, dir: 90, soil: "Kering", moisture: 20 }),
    EARLY_SMOLDERING:  (i) => ({ temp: 33, hum: 58, co: 60 + 6 * i, ch4: 150 + 15 * i, wind: 2.0, dir: 135, soil: "Kering", moisture: 25 }),
    SENSOR_ANOMALY:    (i) => ({ temp: 28, hum: 75, co: 3, ch4: 880 + (i % 3) * 10, wind: 1.5, dir: 180, soil: "Lembap", moisture: 50 }),
    DECAYING:          (i) => ({ temp: 38 - 0.3 * i, hum: 45 + 1.5 * i, co: 230 - 12 * i, ch4: 650 - 30 * i, wind: 2.0, dir: 135, soil: "Lembap", moisture: 40 }),
    ACTIVE_SMOLDERING: (i) => ({ temp: 42, hum: 38, co: 220 + 2 * i, ch4: 650 + 5 * i, wind: 2.5, dir: 225, soil: "Sangat Kering", moisture: 12 }),
    WIND_DRIVEN_FIRE:  (i) => ({ temp: 46, hum: 30, co: 260 + 3 * i, ch4: 700, wind: 7.5 + 0.1 * i, dir: 135, soil: "Sangat Kering", moisture: 8 })
};
const gen = scenarios[scenario];
if (!gen) {
    node.status({ fill: "red", shape: "ring", text: "Unknown scenario: " + scenario });
    node.error("Scenario tidak dikenal: " + scenario + ". Pilihan: " + Object.keys(scenarios).join(", "), msg);
    return null;
}

const clamp01 = v => Math.max(0, Math.min(1, v));
const classify = v => v < 0.4 ? "Low" : v <= 0.6 ? "Moderate" : v <= 0.8 ? "High" : "Extreme";
const dirLabel = deg => ["N", "NE", "E", "SE", "S", "SW", "W", "NW"][Math.round(deg / 45) % 8];
const noise = (i, k, amp) => amp * Math.sin(1.7 * i + k);   // noise deterministik kecil
const round = (v, n) => Number(v.toFixed(n));

const nodeId = `PYROWATCH_SIM_${scenario}`;
const end = Date.now();
const run = end;
for (let i = 0; i < STEPS; i++) {
    const s = gen(i);
    const temp = round(s.temp + noise(i, 0, 0.2), 1);
    const hum = round(Math.min(100, Math.max(0, s.hum + noise(i, 1, 0.8))), 1);
    const co = round(Math.max(0, s.co + noise(i, 2, 3)), 1);
    const ch4 = round(Math.max(0, s.ch4 + noise(i, 3, 10)), 1);
    const fT = clamp01((temp - 25) / 30), fH = clamp01((90 - hum) / 60);
    const fCO = clamp01(co / 200), fCH4 = clamp01(ch4 / 1000), fGas = Math.max(fCO, fCH4);
    const fri = clamp01(0.3 * fT + 0.2 * fH + 0.5 * fGas);
    const ts = new Date(end - (STEPS - 1 - i) * 60000).toISOString();
    const wind = round(s.wind + noise(i, 4, 0.3), 2);
    // baseline spread sama dengan node "hitung spread & arah"
    const wef = Math.exp(wind * 0.045);
    node.send({
        topic: "pyrowatch/test",
        payload: {
            node_id: nodeId, sample_id: `SIM-${scenario}-${run}-${i}`, timestamp: ts,
            temp, hum, co, ch4,
            gas_calibrated: true, gas_calibration_validated: false, gas_calibration_status: "PROVISIONAL",
            fri_f_temperature: fT, fri_f_humidity: fH, fri_f_co: fCO, fri_f_ch4: fCH4, fri_f_gas: fGas,
            fri_base: fri, fri: Number(fri.toFixed(4)), fri_level: classify(fri), fri_data_status: "PROVISIONAL_GAS_INPUT",
            wind_speed_sensor: wind, wind_speed: wind,
            wind_direction_deg: s.dir, wind_direction: dirLabel(s.dir),
            weather_source: "Open-Meteo", weather_status: "SIMULATED", rain: 0,
            soil_condition: s.soil, soil_moisture: s.moisture,
            spread_rate_base_cmph: 2.7, wind_effect_factor: Number(wef.toFixed(4)),
            spread_rate_cmph: Number((2.7 * wef).toFixed(2)),
            spread_model: "SIMULATION_ONLY", spread_model_status: "ESTIMATE",
            spread_label_type: "SEMI_EMPIRICAL_ESTIMATE_NOT_GROUND_TRUTH",
            simulation: true, simulation_scenario: scenario, simulation_step: i + 1, simulation_steps: STEPS
        }
    });
}
node.status({ fill: "green", shape: "dot", text: `${scenario}: ${STEPS} pembacaan dikirim` });
return null;

const all = flow.get("pyrowatch_node_latest") || {};
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
msg.payload = { success: true, count: Object.keys(all).length, data: Object.values(all) };
return msg;
